class HealthPatternTests(unittest.TestCase):
    """Check pattern thresholds, date alignment, missing history, and sleep grouping."""

    def setUp(self) -> None:
        """Create a stable synthetic history with no unusual readings."""
        self.end = date(2026, 10, 24)
        self.metrics: dict[str, dict[str, Any]] = {
            key: {
                "points": [
                    {"date": (self.end - timedelta(days=offset)).isoformat(), "value": value}
                    for offset in range(59, -1, -1)
                ]
            }
            for key, value in (("hrv", 50.0), ("restingHeartRate", 50.0), ("sleep", 8.0))
        }

    def change(self, key: str, offset: int, value: float) -> None:
        """Change one dated reading without changing the rest of its history."""
        self.metrics[key]["points"][-offset - 1]["value"] = value

    def strain(self, offsets: range) -> None:
        """Set low HRV and high resting heart rate on matching dates."""
        for offset in offsets:
            self.change("hrv", offset, 30.0)
            self.change("restingHeartRate", offset, 70.0)

    def test_three_consecutive_days_trigger_joint_recovery_pattern(self) -> None:
        """Require both signals on three adjacent calendar days."""
        self.strain(range(3))
        patterns = build_health_patterns(self.metrics, self.end)
        self.assertEqual([item["id"] for item in patterns], ["recovery-strain"])
        self.assertIn("3 days", patterns[0]["summary"])
        self.assertEqual(patterns[0]["startDate"], (self.end - timedelta(days=2)).isoformat())
        self.assertEqual(patterns[0]["endDate"], self.end.isoformat())

    def test_two_days_or_one_signal_do_not_trigger_joint_pattern(self) -> None:
        """Do not present isolated or short-lived changes as a multi-day pattern."""
        self.strain(range(2))
        self.assertEqual(build_health_patterns(self.metrics, self.end), [])
        self.change("hrv", 2, 30.0)
        self.assertEqual(build_health_patterns(self.metrics, self.end), [])

    def test_history_finds_a_finished_streak_and_merges_daily_detections(self) -> None:
        """Show one dated historical event even when today's readings are normal."""
        self.strain(range(8, 12))
        patterns = build_health_pattern_history(self.metrics, self.end - timedelta(days=29), self.end)
        patterns = [event for event in patterns if event["id"].startswith("recovery-strain:")]
        self.assertEqual(len(patterns), 1)
        event = patterns[0]
        self.assertEqual(event["status"], "historical")
        self.assertEqual(event["startDate"], (self.end - timedelta(days=11)).isoformat())
        self.assertEqual(event["endDate"], (self.end - timedelta(days=8)).isoformat())
        self.assertIn("4 days", event["summary"])
        self.assertNotIn("have moved", event["summary"])
        self.assertIn("isn't a warning about today", event["action"])
        self.assertEqual(build_health_patterns(self.metrics, self.end), [])

    def test_history_keeps_separate_streaks_and_sorts_newest_first(self) -> None:
        """A normal day or missing measurement separates historical events."""
        self.strain(range(3))
        self.strain(range(8, 11))
        for offset in range(3):
            self.change("hrv", offset, 20)
            self.change("restingHeartRate", offset, 80)
        patterns = build_health_pattern_history(self.metrics, self.end - timedelta(days=29), self.end)
        patterns = [event for event in patterns if event["id"].startswith("recovery-strain:")]
        self.assertEqual(len(patterns), 2)
        self.assertEqual(patterns[0]["status"], "recent")
        self.assertEqual(patterns[1]["status"], "historical")
        self.assertEqual(len({event["id"] for event in patterns}), 2)
        self.assertGreater(patterns[0]["endDate"], patterns[1]["endDate"])

    def test_history_excludes_context_only_events(self) -> None:
        """Earlier days build baselines, but cannot become out-of-period cards."""
        self.strain(range(20, 23))
        patterns = build_health_pattern_history(self.metrics, self.end - timedelta(days=6), self.end)
        self.assertTrue(all(event["endDate"] >= (self.end - timedelta(days=6)).isoformat() for event in patterns))
        self.assertFalse(any(event["id"].startswith("recovery-strain:") for event in patterns))

    def test_history_uses_no_future_data_in_earlier_events(self) -> None:
        """Future extremes cannot change a completed historical observation."""
        self.strain(range(8, 11))
        start = self.end - timedelta(days=29)
        before = [
            event for event in build_health_pattern_history(self.metrics, start, self.end)
            if event["id"].startswith("recovery-strain:")
        ]
        self.change("hrv", 0, 999)
        self.change("restingHeartRate", 0, 999)
        after = [
            event for event in build_health_pattern_history(self.metrics, start, self.end)
            if event["id"].startswith("recovery-strain:")
        ]
        self.assertEqual(before, after)

