    def test_hrv_streak_threshold_gaps_and_past_wording(self) -> None:
        """Two days or missing days cannot form a streak; past events are not current advice."""
        days = {self.end - timedelta(days=offset): "below" for offset in range(3, 6)}
        events = _persistent_hrv_patterns(days, self.end - timedelta(days=10), self.end)
        self.assertEqual(len(events), 1)
        self.assertEqual(events[0]["status"], "historical")
        self.assertIn("Think back", events[0]["action"])
        del days[self.end - timedelta(days=4)]
        self.assertEqual(_persistent_hrv_patterns(days, self.end - timedelta(days=10), self.end), [])

