        client.get_daily_sleep_summaries.side_effect = [
            [{"calendarDate": start.isoformat(), "sleepTimeSeconds": 25200, "sleepScores": {"overall": {"value": 70}}}],
            [{"calendarDate": self.end.isoformat(), "sleepTimeSeconds": 28800, "sleepScores": {"overall": {"value": 80}}}],
        ]
