    def test_training_recovery_requires_busy_week_and_return_to_range(self) -> None:
        """Detect recovery after recorded activity, without claiming causation."""
        self.strain(range(2, 5))
        records = [
            {"startTimeLocal": (self.end - timedelta(days=offset)).isoformat(), "duration": minutes * 60}
            for offset, minutes in ((3, 300), (12, 60), (19, 60))
        ]
        patterns = build_health_patterns(self.metrics, self.end, activity_records=records)
        self.assertEqual([item["id"] for item in patterns], ["recovery-after-training"])
        self.assertIn("300 recorded exercise minutes", patterns[0]["evidence"])
        self.assertIn("versus 60 per week", patterns[0]["evidence"])
        self.assertIn("does not show", patterns[0]["evidence"])
        self.assertEqual(build_health_patterns(self.metrics, self.end), [])
        self.assertEqual(build_health_patterns(self.metrics, self.end, activity_records=records[:2]), [])
        records[0]["duration"] = 120 * 60
        self.assertEqual(build_health_patterns(self.metrics, self.end, activity_records=records), [])

    def test_sleep_duration_and_score_count_as_one_warning(self) -> None:
        """Keep both evidence rows but do not escalate a single night's sleep twice."""
        metrics = {
            key: {"label": key, "status": "below_usual", "usualRange28": [6, 8], "unit": ""}
            for key in ("sleep", "sleepScore")
        }
        self.assertIn("Not enough", build_training_briefing(metrics)["approach"])
        metrics["hrv"] = {"label": "HRV", "status": "within_usual", "usualRange28": [45, 60], "unit": "ms"}
        briefing = build_training_briefing(metrics)
        self.assertEqual(briefing["approach"], "Keep today flexible.")
        self.assertEqual(len(briefing["evidence"]), 2)
        changed = deepcopy(metrics)
        changed["hrv"]["status"] = "below_usual"
        self.assertEqual(build_training_briefing(changed)["approach"], "Consider rest or an easy session today.")


